public class PaymentProcessor {
    private Map<String, Transaction> pendingTransactions = new ConcurrentHashMap<>();

    public void processPayment(String transactionId, Amount amount) {
        if (!pendingTransactions.containsKey(transactionId)) {
            return;
        }

        Transaction txn = pendingTransactions.get(transactionId);
        txn.setStatus(TransactionStatus.PROCESSING);

        if (amount.compareTo(new Amount(0)) > 0) {
            txn.addAmount(amount);
            txn.setStatus(TransactionStatus.COMPLETED);
        } else {
            txn.setStatus(TransactionStatus.FAILED);
        }
    }
}
